#!/usr/bin/env python3
import format_comment


def test_target_branches_derived_from_affected_versions():
    data = {
        'patch_summary': '补丁摘要',
        'affected_versions': {
            'master': {'status': '受影响'},
            'openEuler-22.03-LTS-SP4': {'status': '不受影响'},
            'openEuler-24.03-LTS': {'status': '受影响'},
        },
        'target_branches': ['should-be-ignored'],
    }
    result = format_comment.format_upstream_comment(data)
    assert '目标分支：' in result
    assert '- master' in result
    assert '- openEuler-24.03-LTS' in result
    assert 'should-be-ignored' not in result
    target_section = result.split('目标分支：', 1)[1].split('原因说明', 1)[0]
    assert 'openEuler-22.03-LTS-SP4' not in target_section

