#!/usr/bin/env python3
import format_comment


def test_reasons_section_present():
    data = {
        'patch_summary': '补丁摘要',
        'reasons': {
            'master': {'reason': '正常修复'},
            'openEuler-24.03-LTS': {'reason': '暂不修复-漏洞仍在分析中'},
        },
    }
    result = format_comment.format_upstream_comment(data)
    assert '原因说明：' in result
    assert '- master: 正常修复' in result
    assert '- openEuler-24.03-LTS: 暂不修复-漏洞仍在分析中' in result


def test_patch_summary_still_works():
    data = {
        'patch_summary': '这是一个补丁摘要',
    }
    result = format_comment.format_upstream_comment(data)
    assert result.startswith('上游补丁回合结果')
    assert '这是一个补丁摘要' in result


def test_pr_links_still_works():
    data = {
        'pr_links': [
            {'branch': 'master', 'pr_url': 'http/workspace/example.com/pr/1'},
            {'branch': '', 'pr_url': 'http/workspace/example.com/pr/2'},
        ],
    }
    result = format_comment.format_upstream_comment(data)
    assert 'PR：' in result
    assert '- master: http/workspace/example.com/pr/1' in result
    assert '- http/workspace/example.com/pr/2' in result


def test_empty_data_minimal_output():
    data = {}
    result = format_comment.format_upstream_comment(data)
    assert result.startswith('上游补丁回合结果')
    assert '目标分支' not in result
    assert '原因说明' not in result
    assert 'PR：' not in result
